const fs=require("node:fs"),path=require("node:path"),m=require("node:module"),u=require("node:url");
(async()=>{
try{
const file=path.resolve(process.argv[2]||process.argv[1]);
if(!fs.existsSync(file)){console.error("file not found: "+file);process.exit(2);}
const req=m.createRequire(path.join(path.dirname(file),"a.js"));
let entry;
try{entry=req.resolve("npm-groovy-lint");}catch(e){console.error("npm-groovy-lint not resolvable from "+file+" (install it as project devDependency): "+e.message);process.exit(2);}
const mod=await import(u.pathToFileURL(entry).href);
const NpmGroovyLint=mod.default;
const RULES="ElseBlockBraces,ForStatementBraces,IfStatementBraces,WhileStatementBraces,NoTabCharacter,BlankLineBeforePackage,BlockEndsWithBlankLine,BlockStartsWithBlankLine,BracesForClass,BracesForForLoop,BracesForIfElse,BracesForMethod,BracesForTryCatchFinally,ClassEndsWithBlankLine,ClassStartsWithBlankLine,ClosureStatementOnOpeningLineOfMultipleLineClosure,ConsecutiveBlankLines,FileEndsWithoutNewline,Indentation,MissingBlankLineAfterImports,MissingBlankLineAfterPackage,SpaceAfterCatch,SpaceAfterClosingBrace,SpaceAfterComma,SpaceAfterFor,SpaceAfterIf,SpaceAfterMethodCallName,SpaceAfterOpeningBrace,SpaceAfterSemicolon,SpaceAfterSwitch,SpaceAfterWhile,SpaceAroundClosureArrow,SpaceAroundMapEntryColon,SpaceAroundOperator,SpaceBeforeClosingBrace,SpaceBeforeOpeningBrace,SpaceInsideParentheses,TrailingWhitespace,UnnecessaryGString,UnnecessarySemicolon";
const linter=new NpmGroovyLint([process.execPath,"npm-groovy-lint",file,"--rulesets",RULES,"--failon","none","--output","json","--noserver"],{origin:"codeguard",parseOptions:true});
const realWrite=process.stdout.write.bind(process.stdout);
process.stdout.write=()=>true;
let err=null;
try{await linter.run();}catch(e){err=e;}
process.stdout.write=realWrite;
if(err){console.error("npm-groovy-lint threw: "+err.message);process.exit(2);}
if(linter.status===2){console.error("npm-groovy-lint unexpected failure (check java/CodeNarc availability)");process.exit(2);}
const result=linter.lintResult||{};
let violations=0,parseErrors=0;
const files=(result&&result.files)||{};
for(const key of Object.keys(files)){
for(const issue of (files[key].errors||[])){
const rule=issue&&issue.rule;
if(rule==="NglParseError"){parseErrors++;}else{violations++;}
}}
if(parseErrors>0){console.error("groovy parse error: cannot judge formatting");process.exit(2);}
if(linter.status!==0&&violations===0){console.error("npm-groovy-lint status "+linter.status+" with no violations");process.exit(2);}
process.exit(violations>0?1:0);
}catch(e){console.error("wrapper error: "+(e&&e.message));process.exit(2);}
})();

