const fs=require("node:fs"),path=require("node:path"),m=require("node:module"),u=require("node:url");
(async()=>{
try{
const file=path.resolve(process.argv[2]||process.argv[1]);
if(!fs.existsSync(file)){console.error("file not found: "+file);process.exit(2);}
const req=m.createRequire(path.join(path.dirname(file),"a.js"));
let entry;
try{entry=req.resolve("npm-groovy-lint");}catch(e){console.error("npm-groovy-lint not resolvable from "+file+" (install it as project devDependency): "+e.message);process.exit(2);}
const mod=await import(u.pathToFileURL(entry).href);
const NpmGroovyLint=mod.default;
const quietRun=async(argv)=>{
const linter=new NpmGroovyLint(argv,{origin:"codeguard",parseOptions:true});
const realWrite=process.stdout.write.bind(process.stdout);
process.stdout.write=()=>true;
let err=null;
try{await linter.run();}catch(e){err=e;}
process.stdout.write=realWrite;
return {linter,err};
};
const countParseErrors=(linter)=>{
const result=linter.lintResult||{};
let parseErrors=0;
const files=(result&&result.files)||{};
for(const key of Object.keys(files)){
for(const issue of (files[key].errors||[])){
if(issue&&issue.rule==="NglParseError"){parseErrors++;}
}}
return parseErrors;
};
const pre=[process.execPath,"npm-groovy-lint",file,"--parse","--failon","none","--output","json","--noserver"];
const pre1=await quietRun(pre);
if(pre1.err){console.error("npm-groovy-lint threw: "+pre1.err.message);process.exit(2);}
if(pre1.linter.status===2){console.error("npm-groovy-lint unexpected failure (check java/CodeNarc availability)");process.exit(2);}
if(countParseErrors(pre1.linter)>0){console.error("groovy parse error: formatting refused, file untouched");process.exit(2);}
const main=[process.execPath,"npm-groovy-lint",file,"--format","--nolintafter","--parse","--failon","none","--output","json","--noserver"];
const main1=await quietRun(main);
if(main1.err){console.error("npm-groovy-lint threw: "+main1.err.message);process.exit(2);}
if(main1.linter.status===2){console.error("npm-groovy-lint unexpected failure during format");process.exit(2);}
if(countParseErrors(main1.linter)>0){console.error("groovy parse error during format");process.exit(2);}
process.exit(0);
}catch(e){console.error("wrapper error: "+(e&&e.message));process.exit(2);}
})();

