const fs=require("node:fs"),path=require("node:path"),m=require("node:module");
(async()=>{
try{
const mode=process.argv[1];
const file=path.resolve(process.argv[2]);
if(!fs.existsSync(file)){console.error("file not found: "+file);process.exit(2);}
const req=m.createRequire(path.join(path.dirname(file),"a.js"));
let oxkPath;
try{oxkPath=req.resolve("@ohos-rs/oxk/format");}catch(e){console.error("@ohos-rs/oxk not resolvable from "+file+" (install it as project devDependency): "+e.message);process.exit(2);}
const oxk=req(oxkPath);
const src=fs.readFileSync(file,"utf8");
let result;
try{result=await oxk.format(file,src,{});}catch(e){console.error("oxk format error: file left untouched, "+e.message);process.exit(2);}
const errors=(result&&result.errors)||[];
if(errors.length>0){console.error("arkts parse error: file left untouched, "+errors.join("; "));process.exit(2);}
const out=result.code;
if(mode==="apply"){if(out!==src){fs.writeFileSync(file,out);}process.exit(0);}
process.exit(out===src?0:1);
}catch(e){console.error("wrapper error: "+(e&&e.message));process.exit(2);}
})();

